import{Helper}from"../Helper";export const CurrencySymbol=Object.freeze({USD:"$",GBP:"£",EUR:"€"});export const BillingCycle={MONTHLY:1,ANNUAL:12,LIFETIME:0};export const BillingCycleString={MONTHLY:"monthly",ANNUAL:"annual",LIFETIME:"lifetime"};export const DefaultCurrency="usd";export const UnlimitedLicenses=99999;export class Pricing{plan_id=null;licenses=1;monthly_price=null;annual_price=null;lifetime_price=null;currency=DefaultCurrency;is_hidden=false;constructor(object=null){if(null==object){return}for(const p in object){if(object.hasOwnProperty(p)){this[p]=object[p]}}}static getBillingCyclePeriod(billingCycle){if(!Helper.isNumeric(billingCycle)){if(!Helper.isNonEmptyString(billingCycle)||!Helper.inArray(billingCycle,[BillingCycleString.MONTHLY,BillingCycleString.ANNUAL,BillingCycleString.LIFETIME])){billingCycle=BillingCycleString.ANNUAL}return billingCycle}billingCycle=parseInt(billingCycle);switch(billingCycle){case BillingCycle.MONTHLY:return BillingCycleString.MONTHLY;case BillingCycle.LIFETIME:return BillingCycleString.LIFETIME;case BillingCycle.ANNUAL:default:return BillingCycleString.ANNUAL}}static getBillingCycleInMonths(billingCycle){if(Helper.isNumeric(billingCycle)){billingCycle=parseInt(billingCycle);if(!Helper.inArray(billingCycle,[BillingCycle.MONTHLY,BillingCycle.ANNUAL,BillingCycle.LIFETIME])){billingCycle=BillingCycle.ANNUAL}return billingCycle}if(!Helper.isNonEmptyString(billingCycle)){return BillingCycle.ANNUAL}switch(billingCycle){case BillingCycleString.MONTHLY:return BillingCycle.MONTHLY;case BillingCycleString.LIFETIME:return BillingCycle.LIFETIME;case BillingCycleString.ANNUAL:default:return BillingCycle.ANNUAL}}getAmount(billingCycle,format,locale){let amount=0;switch(billingCycle){case BillingCycle.MONTHLY:amount=this.monthly_price;break;case BillingCycle.ANNUAL:amount=this.annual_price;break;case BillingCycle.LIFETIME:amount=this.lifetime_price;break}amount=parseFloat(amount);if(format){amount=Helper.formatNumber(amount,locale)}return amount}getMonthlyAmount(billingCycle,format,locale){let amount=0;switch(billingCycle){case BillingCycle.MONTHLY:amount=this.hasMonthlyPrice()?this.monthly_price:this.annual_price/12;break;case BillingCycle.ANNUAL:amount=this.hasAnnualPrice()?this.annual_price/12:this.monthly_price;break}amount=parseFloat(amount);if(format){amount=Helper.formatNumber(amount,locale)}return amount}getLicenses(){return this.isUnlimited()?UnlimitedLicenses:this.licenses}hasAnnualPrice(){return Helper.isNumeric(this.annual_price)&&this.annual_price>0}hasLifetimePrice(){return Helper.isNumeric(this.lifetime_price)&&this.lifetime_price>0}hasMonthlyPrice(){return Helper.isNumeric(this.monthly_price)&&this.monthly_price>0}isFree(){return!this.hasMonthlyPrice()&&!this.hasAnnualPrice()&&!this.hasLifetimePrice()}isSingleSite(){return 1==this.licenses}isUnlimited(){return null==this.licenses}sitesLabel(){let sites="";if(this.isSingleSite())sites="Single";else if(this.isUnlimited())sites="Unlimited";else sites=this.licenses;return sites+" Site"+(this.isSingleSite()?"":"s")}supportsBillingCycle(billingCycle){return null!==this[`${billingCycle}_price`]}}